package bench96f863ed7c4e415cba91c649f12d805a;
import org.voltdb.*;
public final class Q6 extends VoltProcedure {
    public final SQLStmt query = new SQLStmt("SELECT DISTINCT r.id FROM kiara_records_3407626098674141aa10206b890c4eab r JOIN kiara_vals_3407626098674141aa10206b890c4eab v0 ON v0.id = r.id AND v0.field = ? AND ((v0.text_value = ?)) WHERE (r.f_price_num >= ? AND r.f_price_num <= ?)");
    public VoltTable[] run(int bucket, String p0, String p1, double p2, double p3) {
        long clockStart = System.nanoTime();
        long timerPair = System.nanoTime() - clockStart;
        Object[] arguments = new Object[]{p0, p1, p2, p3};
        long start = System.nanoTime();
        voltQueueSQL(query, arguments);
        VoltTable[] rows = voltExecuteSQL(true);
        long elapsed = System.nanoTime() - start;
        VoltTable timing = new VoltTable(new VoltTable.ColumnInfo("EXECUTION_NS", VoltType.BIGINT),
                new VoltTable.ColumnInfo("TIMER_PAIR_NS", VoltType.BIGINT));
        timing.addRow(elapsed, timerPair);
        return new VoltTable[]{rows[0], timing};
    }
}

